const fs = require('fs/promises');

async function manageFiles() {
  try {
    // 1. Write to a file (creates it if it doesn't exist)
    await fs.writeFile('example.txt', 'Hello, Node.js!');
    console.log("File created successfully.");

    // 2. Append data to the file
    await fs.appendFile('example.txt', '\nAdding a second line.');

    // 3. Read the file (MUST provide 'utf-8', otherwise it returns a raw Buffer)
    const data = await fs.readFile('example.txt', 'utf-8');
    console.log("\n--- FILE CONTENT ---");
    console.log(data);
    console.log("--------------------\n");

    // 4. Delete the file to clean up
    // await fs.unlink('example.txt');

  } catch (err) {
    console.error("An error occurred:", err);
  }
}

manageFiles();
